-- IPA 2021-12-12 individually checked adaptations and repeat.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20211212-q01','exam-fe','論理演算','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問1・改編】nビット値L1、L2について、X=L1 OR L2、Y=NOT(L1 AND L2)、L3=X AND Yとする。L3と等しいビット演算はどれか。','[{"id":"a","text":"排他的論理和"},{"id":"b","text":"排他的論理和の否定"},{"id":"c","text":"論理積の否定"},{"id":"d","text":"論理和の否定"}]','"a"','(L1 OR L2) AND NOT(L1 AND L2)は両ビットが異なるとき1になるXOR。中文：或运算与与非运算再取与，得到异或。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q02','exam-fe','相関係数','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問2・改編】4つの散布図はそれぞれ相関係数−0.9、−0.7、0.7、0.9に対応する。−0.9に対応する特徴はどれか。','[{"id":"a","text":"右上がりの直線の周囲に点が密集"},{"id":"b","text":"右上がりの直線の周囲に点が比較的広く散る"},{"id":"c","text":"右下がりの直線の周囲に点が密集"},{"id":"d","text":"右下がりの直線の周囲に点が比較的広く散る"}]','"c"','負の相関は右下がり、絶対値が1に近いほど点が直線に近い。中文：−0.9是较强负相关，点靠近下降直线。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q03','exam-fe','期待値','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問3・改編】公平なサイコロを振り1〜4なら出た目を得点、5と6なら0点とする。1回の得点の期待値はどれか。','[{"id":"a","text":"5/3"},{"id":"b","text":"7/3"},{"id":"c","text":"5/2"},{"id":"d","text":"20/3"}]','"a"','(1＋2＋3＋4＋0＋0)÷6＝5/3。中文：六种结果等概率，得分和10除以6得到5/3。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q04','exam-fe','行基本変形','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問4・改編】行列(2,3,4; 5,6,7)に操作a,b,c,dを順に施し、(2,3,4; 1,0,−1)、(1,0,−1; 2,3,4)、(1,0,−1; 0,3,6)、(1,0,−1; 0,1,2)と変化した。同じ種類の行基本操作を行った組合せはどれか。','[{"id":"a","text":"aとb"},{"id":"b","text":"aとc"},{"id":"c","text":"bとc"},{"id":"d","text":"bとd"}]','"b"','aは第2行から第1行の2倍を引く。cは第2行から第1行の2倍を引く。bは交換、dは定数倍。中文：a和c都是向一行加上另一行的倍数。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q05','exam-fe','探索の計算量','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問5・改編】データ数nの二分探索、線形探索、ハッシュ探索の実行時間のオーダの組合せはどれか。ハッシュ衝突は無視できるものとする。','[{"id":"a","text":"log₂n、n、1"},{"id":"b","text":"n log₂n、n、log₂n"},{"id":"c","text":"n log₂n、n²、1"},{"id":"d","text":"n²、1、n"}]','"a"','二分探索は対象を半減、線形探索は順に確認、衝突が無視できるハッシュ探索は定数時間。中文：分别为对数、线性和常数阶。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q06','exam-fe','符号化','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問6・改編】a,b,c,dの出現頻度は50%、30%、10%、10%。次の符号表で一意に復号でき、平均ビット長が最も短いものはどれか。','[{"id":"a","text":"a=0,b=1,c=00,d=11"},{"id":"b","text":"a=0,b=01,c=10,d=11"},{"id":"c","text":"a=0,b=10,c=110,d=111"},{"id":"d","text":"a=00,b=01,c=10,d=11"}]','"c"','cは接頭語を持たず平均1.7ビット。dは2ビット、aとbは一意復号できない。中文：选项c是前缀码，平均长度1.7位，短于固定2位编码。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q07','exam-fe','スタック','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問7・改編】配列Aと初期値0のpに対し、f(x)はpを1増やしてA[p]にxを格納し、g()はA[p]を取得してpを1減らす。これらが操作するデータ構造はどれか。','[{"id":"a","text":"キュー"},{"id":"b","text":"スタック"},{"id":"c","text":"ハッシュ"},{"id":"d","text":"ヒープ"}]','"b"','最後に格納したデータから取り出す後入れ先出しなのでスタック。中文：最后放入的数据先取出，即栈。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q09','exam-fe','プログラミング言語','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問9・改編】クラス、関数、条件文などのコードブロックの範囲をインデントの深さで指定する言語はどれか。','[{"id":"a","text":"JavaScript"},{"id":"b","text":"Perl"},{"id":"c","text":"Python"},{"id":"d","text":"Ruby"}]','"c"','Pythonはインデントを用いてブロックを表現する。中文：Python用缩进界定代码块。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q10','exam-fe','XML','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問10・改編】XMLの特徴として最も適切なものはどれか。','[{"id":"a","text":"HTMLにWebページ表示性能向上の機能を追加したもの"},{"id":"b","text":"データ交換を容易にするため任意のタグを定義できる"},{"id":"c","text":"使用できるスタイル言語はHTMLと同じものだけである"},{"id":"d","text":"SGMLと無関係の独自仕様として開発された"}]','"b"','XMLでは用途に応じたタグを定義して構造化データを表現する。中文：XML可定义标签，表达便于交换的结构化数据。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q11','exam-fe','CPU性能','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問11・改編】1GHzのCPUで機械語1命令を平均0.8クロックで実行できる。1秒当たりの平均命令数は何万命令か。','[{"id":"a","text":"125"},{"id":"b","text":"250"},{"id":"c","text":"80000"},{"id":"d","text":"125000"}]','"d"','10億クロック÷0.8＝12億5000万命令、万命令単位で125000。中文：每秒10亿周期除以0.8，得到12.5亿条指令。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q12','exam-fe','パイプライン','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問12・改編】命令処理の段階はF=フェッチ、D=解読、E=実行。パイプライン制御を正しく表すものはどれか。','[{"id":"a","text":"各命令をF→D→Eで処理するが前命令終了後に次を開始"},{"id":"b","text":"各命令をD→F→Eの順で1段ずつずらす"},{"id":"c","text":"各命令をF→D→Eの順で1段ずつずらして重ねる"},{"id":"d","text":"各命令をD→F→Eの順で同時に開始する"}]','"c"','各命令の処理順を守り、異なる命令の異なる段階を重ねて実行する。中文：各指令按取指、译码、执行顺序错开重叠。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q13','exam-fe','RAID','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問13・改編】ミラーリングで信頼性を高め、故障時に冗長ディスクを用いて復元するRAID方式はどれか。','[{"id":"a","text":"RAID1"},{"id":"b","text":"RAID2"},{"id":"c","text":"RAID3"},{"id":"d","text":"RAID4"}]','"a"','RAID1は同じデータを複数のディスクに書くミラーリング。中文：RAID1通过镜像在多个磁盘保存相同数据。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q14','exam-fe','ビデオメモリ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問14・改編】横1024画素、縦768画素、1画素24ビットの画面に必要なメモリ量は約何Mバイトか。1Mバイト＝10⁶バイトとする。','[{"id":"a","text":"0.8"},{"id":"b","text":"2.4"},{"id":"c","text":"6.3"},{"id":"d","text":"18.9"}]','"b"','1024×768×24÷8＝2359296バイトで約2.4MB。中文：每像素3字节，总计约2.4MB。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q15','exam-fe','稼働率','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問15・改編】MTBF45時間、MTTR5時間の同一装置2台を直列接続する。装置の故障は独立とするとシステム稼働率はどれか。','[{"id":"a","text":"0.81"},{"id":"b","text":"0.90"},{"id":"c","text":"0.95"},{"id":"d","text":"0.99"}]','"a"','1台の稼働率45/(45＋5)=0.9。直列は両方必要なので0.9²＝0.81。中文：单台可用率0.9，两台串联相乘得0.81。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q16','exam-fe','スループット','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問16・改編】一定時間内にシステムが処理する仕事量を表す用語はどれか。','[{"id":"a","text":"アクセスタイム"},{"id":"b","text":"オーバヘッド"},{"id":"c","text":"スループット"},{"id":"d","text":"ターンアラウンドタイム"}]','"c"','スループットは単位時間当たりの処理量。中文：吞吐量表示单位时间内完成的工作量。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q17','exam-fe','仮想記憶','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問17・改編】記憶空間を一定の大きさに区切って管理し、仮想記憶を実現する方式はどれか。','[{"id":"a","text":"スラッシング"},{"id":"b","text":"スワッピング"},{"id":"c","text":"ブロッキング"},{"id":"d","text":"ページング"}]','"d"','ページングでは固定長のページに分割し、ページ単位で管理する。中文：分页将虚拟地址空间按固定大小划分并管理。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q18','exam-fe','キャッシュ置換','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問18・改編】キャッシュC0〜C3のロード時刻・最終参照時刻・参照回数は順にC0=(0:00,0:08,10)、C1=(0:03,0:06,1)、C2=(0:04,0:05,3)、C3=(0:05,0:10,5)。C2を置換する方式はどれか。','[{"id":"a","text":"FIFO"},{"id":"b","text":"LFU"},{"id":"c","text":"LIFO"},{"id":"d","text":"LRU"}]','"d"','C2の最終参照時刻が最も古いためLRUで選ばれる。中文：C2距上次访问最久，最近最少使用算法选择它。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q19','exam-fe','ハッシュ法','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問19・改編】アドレス1〜6にキー3,4,8,13,14,18を順に格納する。初期アドレスはキーを5で割った余り＋1。使用済みなら次のアドレスを探し、6の次は1に戻る。最後にアドレス1にあるキーはどれか。','[{"id":"a","text":"8"},{"id":"b","text":"13"},{"id":"c","text":"14"},{"id":"d","text":"18"}]','"b"','3→4、4→5、8→6、13は4〜6が埋まっているので1へ格納。中文：键13散列到4，线性探测绕回后存入1。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q20','exam-fe','D/A変換','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問20・改編】8ビットD/A変換器は値0の出力が0mV、最下位ビット1の増加が10mVに対応する。16進数82を入力したときの出力は何mVか。','[{"id":"a","text":"820"},{"id":"b","text":"1024"},{"id":"c","text":"1300"},{"id":"d","text":"1312"}]','"c"','16進82は10進130なので130×10＝1300mV。中文：十六进制82等于十进制130，乘以10mV得1300mV。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q21','exam-fe','DRAM','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問21・改編】DRAMの説明として適切なものはどれか。','[{"id":"a","text":"1バイト単位で消去・書込みが可能な不揮発性メモリ"},{"id":"b","text":"NAND型又はNOR型がありSSDに使われる不揮発性メモリ"},{"id":"c","text":"フリップフロップで構成されキャッシュに使われるメモリ"},{"id":"d","text":"リフレッシュ動作が必要でPCの主記憶に使われるメモリ"}]','"d"','DRAMは保持電荷が失われるため定期的なリフレッシュが必要。中文：DRAM需要刷新，常用于计算机主存。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q22','exam-fe','多数決回路','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問22・改編】3入力A,B,Cのうち2個以上が1なら1を出力する多数決回路の論理式はどれか。∧はAND、∨はOR、⊕はXORとする。','[{"id":"a","text":"(A∧B)∨(B∧C)∨(A∧C)"},{"id":"b","text":"(A⊕B)∨(B⊕C)∨(A⊕C)"},{"id":"c","text":"¬((A∨B)∧(B∨C)∧(A∨C))"},{"id":"d","text":"¬((A⊕B)∧(B⊕C)∧(A⊕C))"}]','"a"','2個以上が1ならいずれかの2入力のANDが1となる。中文：任意两位同时为1即可满足多数决，三个两两与运算再取或。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q23','exam-fe','Webアクセシビリティ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問23・改編】Webページでアクセシビリティを高める設計として最も適切なものはどれか。','[{"id":"a","text":"ページ表示と同時に音声を自動再生する"},{"id":"b","text":"レイアウトを整えるため表組みを使う"},{"id":"c","text":"必須項目を色だけで示さず項目名の隣に「必須」と明記する"},{"id":"d","text":"画像リンクのalt属性にリンク先URLだけを記載する"}]','"c"','色以外の文字情報も加えれば色の識別が難しい利用者にも伝わる。中文：不能仅靠颜色表达必填，应同时提供文字提示。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q26','exam-fe','関係演算','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問26・改編】関係モデルで、関係から特定の属性だけを取り出す演算はどれか。','[{"id":"a","text":"結合"},{"id":"b","text":"射影"},{"id":"c","text":"選択"},{"id":"d","text":"和"}]','"b"','射影は列（属性）を取り出す。選択は条件に合う行を取り出す。中文：投影选择列，选择运算筛选行。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q27','exam-fe','SQL結合','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問27・改編】社員の所属は総務1人、経理1人、営業4人、情報システム2人、企画1人。部門のフロアは企画・総務が1、情報システム・経理・法務・購買が2、営業が3である。社員と部門を所属＝部門名で結合しフロア2の行をCOUNT(*)すると幾つか。','[{"id":"a","text":"1"},{"id":"b","text":"2"},{"id":"c","text":"3"},{"id":"d","text":"4"}]','"c"','フロア2のうち社員がいるのは経理1人と情報システム2人。中文：二楼的经理由1人、信息系统由2人，共3人。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q28','exam-fe','データベースロック','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問28・改編】排他制御で、あるトランザクションが取得中の資源に別のトランザクションが新たにロックを取得できる組合せはどれか。','[{"id":"a","text":"既存が共有ロックで新規も共有ロック"},{"id":"b","text":"既存が共有ロックで新規は専有ロック"},{"id":"c","text":"既存が専有ロックで新規は共有ロック"},{"id":"d","text":"既存が専有ロックで新規も専有ロック"}]','"a"','共有ロック同士は共存できるが、専有ロックは他のロックと両立しない。中文：共享锁可以并存，排他锁不能与其他锁并存。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q29','exam-fe','ロールフォワード','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問29・改編】媒体障害で最新バックアップをリストアした後、トランザクションログを使って行う操作はどれか。','[{"id":"a","text":"バックアップ後コミット前に中断した処理をロールバック"},{"id":"b","text":"バックアップ後コミット前に中断した処理をロールフォワード"},{"id":"c","text":"バックアップ後コミットした処理をロールバック"},{"id":"d","text":"バックアップ後コミットした処理をロールフォワード"}]','"d"','バックアップ時点以降に確定した更新をログから再適用する。中文：恢复备份后，对之后已提交的事务执行前滚。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q30','exam-fe','ビット誤り率','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問30・改編】30Mビット/秒の回線で100秒に平均1回、1ビット誤りが発生した。ビット誤り率はどれか。','[{"id":"a","text":"4.17×10⁻¹¹"},{"id":"b","text":"3.33×10⁻¹⁰"},{"id":"c","text":"4.17×10⁻⁵"},{"id":"d","text":"3.33×10⁻⁴"}]','"b"','100秒に送るのは30×10⁶×100＝3×10⁹ビット。1÷(3×10⁹)＝3.33×10⁻¹⁰。中文：30亿比特平均错1位，误码率约3.33×10⁻¹⁰。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q31','exam-fe','DHCP','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問31・改編】DHCPの説明として適切なものはどれか。','[{"id":"a","text":"IPアドレスの設定を自動化するプロトコル"},{"id":"b","text":"ディレクトリサービスにアクセスするプロトコル"},{"id":"c","text":"電子メールを転送するプロトコル"},{"id":"d","text":"プライベートIPをグローバルIPに変換するプロトコル"}]','"a"','DHCPはIPアドレスなどのネットワーク設定を自動配布する。中文：DHCP自动配置IP地址等网络参数。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q32','exam-fe','MIME','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問32・改編】電子メールのヘッダを拡張し、テキスト以外に音声や画像などを扱えるようにした規格はどれか。','[{"id":"a","text":"HTML"},{"id":"b","text":"MHS"},{"id":"c","text":"MIME"},{"id":"d","text":"SMTP"}]','"c"','MIMEはメール本文の形式やエンコードを拡張し画像などを扱えるようにする。中文：MIME扩展邮件格式，使邮件能够包含图片、音频等内容。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q33','exam-fe','NAPT','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問33・改編】ポート番号とIPアドレスの対応を管理し、LAN内の複数端末が1つのグローバルIPを共有する仕組みはどれか。','[{"id":"a","text":"IPスプーフィング"},{"id":"b","text":"IPマルチキャスト"},{"id":"c","text":"NAPT"},{"id":"d","text":"NTP"}]','"c"','NAPTはアドレスとポート番号を変換して複数端末の通信を識別する。中文：网络地址端口转换让多个内部终端共享公网IP。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q35','exam-fe','TLS証明書','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問35・改編】PCがTLS接続でサーバ証明書を受け取った後、認証局の公開鍵を使って行う動作はどれか。','[{"id":"a","text":"通信の共通鍵を復号する"},{"id":"b","text":"通信の共通鍵を生成し暗号化する"},{"id":"c","text":"サーバ証明書の正当性を検証する"},{"id":"d","text":"利用者の秘密データを暗号化する"}]','"c"','認証局の署名を公開鍵で検証し、証明書の正当性を確認する。中文：使用CA公钥验证证书签名，确认服务器证书的真实性。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q36','exam-fe','情報の完全性','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問36・改編】情報の完全性を脅かす攻撃はどれか。','[{"id":"a","text":"Webページの改ざん"},{"id":"b","text":"保存データの不正コピー"},{"id":"c","text":"DoS攻撃"},{"id":"d","text":"通信内容の盗聴"}]','"a"','完全性は情報が不正に変更されない性質。改ざんがこれを損なう。中文：完整性关注数据是否被未授权篡改。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q37','exam-fe','ゼロデイ攻撃','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問37・改編】ゼロデイ攻撃の特徴はどれか。','[{"id":"a","text":"修正パッチが提供される前に脆弱性を悪用する"},{"id":"b","text":"日時を決め複数PCから特定サイトを同時攻撃する"},{"id":"c","text":"フィッシングメールで特定の標的を偽サイトへ誘導する"},{"id":"d","text":"不正中継可能なメールサーバから大量のチェーンメールを送る"}]','"a"','対策パッチが利用可能になる前に脆弱性が攻撃される。中文：零日攻击利用尚无修补程序可用的漏洞。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q38','exam-fe','ディジタル署名','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問38・改編】送信者Aの文書とディジタル署名を受信者Bが受け取り、Aの署名検証鍵を持つ。検証で確認できることはどれか。','[{"id":"a","text":"改ざん箇所を特定できる"},{"id":"b","text":"文書が改ざんされておらず、対応する署名生成鍵による署名であること"},{"id":"c","text":"文書がマルウェアに感染していないこと"},{"id":"d","text":"文書と署名のどちらが改ざんされたかの特定"}]','"b"','検証は文書の完全性と対応する秘密鍵による署名を確認するが、改ざん箇所や感染の有無は分からない。中文：签名验证可检查完整性及签名密钥对应关系，无法定位篡改位置。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q39','exam-fe','共通鍵暗号','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問39・改編】データの暗号化と復号に同じ鍵を使う暗号方式はどれか。','[{"id":"a","text":"AES"},{"id":"b","text":"PKI"},{"id":"c","text":"RSA"},{"id":"d","text":"SHA-256"}]','"a"','AESは共通鍵暗号。RSAは公開鍵暗号、SHA-256はハッシュ関数。中文：AES使用对称密钥；RSA是非对称密码，SHA-256是哈希算法。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q43','exam-fe','パスワード攻撃対策','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問43・改編】辞書攻撃、スニッフィング、ブルートフォース攻撃のそれぞれに対する対策の組合せはどれか。','[{"id":"a","text":"推測されにくいパスワード、通信時の暗号化、試行回数の制限"},{"id":"b","text":"推測されにくいパスワード、試行回数の制限、通信時の暗号化"},{"id":"c","text":"通信時の暗号化、試行回数の制限、推測されにくいパスワード"},{"id":"d","text":"試行回数の制限、推測されにくいパスワード、通信時の暗号化"}]','"a"','推測困難なパスワードは辞書攻撃を、暗号化通信は盗聴を、試行制限は総当たりを抑える。中文：复杂密码应对字典攻击、传输加密应对嗅探、限制尝试次数应对暴力破解。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q44','exam-fe','パスワードの保存','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問44・改編】登録パスワードを保存するファイルへの不正アクセスに備える方法はどれか。','[{"id":"a","text":"利用者IDのハッシュ値を保存し、登録パスワードと入力パスワードを比較する"},{"id":"b","text":"パスワードの平文ファイルを圧縮する"},{"id":"c","text":"パスワードの平文を保存し認証時に双方をハッシュ化する"},{"id":"d","text":"パスワードのハッシュ値を保存し入力値のハッシュと比較する"}]','"d"','平文を保存せずハッシュ値で検証する。実運用ではソルト付きのパスワード専用ハッシュを使う。中文：保存加盐的密码专用哈希值，验证时比较哈希，避免明文保存。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q45','exam-fe','ユースケース図','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問45・改編】UMLのユースケース図の説明はどれか。','[{"id":"a","text":"外部トリガによるオブジェクトの状態遷移を表す"},{"id":"b","text":"クラスと関連でシステムの静的構造を表す"},{"id":"c","text":"システムとアクタの相互作用を表す"},{"id":"d","text":"データの流れに注目して機能を表す"}]','"c"','ユースケース図はアクタとシステムが提供する機能の関係を表す。中文：用例图描述参与者与系统功能的交互。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q46','exam-fe','クラス','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問46・改編】オブジェクト指向言語のクラスについて適切なものはどれか。','[{"id":"a","text":"インスタンス変数はクラス全体の共有データである"},{"id":"b","text":"オブジェクトに共通する性質を定義したものがクラスであり、クラスを集めたものがクラスライブラリである"},{"id":"c","text":"クラスにメソッドと呼ばれる共有データが保存される"},{"id":"d","text":"スーパークラスがサブクラスの性質を継承する"}]','"b"','クラスはオブジェクトの共通の性質を定義し、関連するクラスをライブラリとして利用できる。中文：类定义对象的共同属性和行为，类库汇集可复用的类。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q48','exam-fe','SOA','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問48・改編】SOAの説明はどれか。','[{"id":"a","text":"Webサービスのインタフェースとプロトコルを規定する"},{"id":"b","text":"XMLを用いてWebサービスを検索する仕組み"},{"id":"c","text":"業務機能を提供するサービスを組み合わせシステムを構築する考え方"},{"id":"d","text":"サービス提供者と顧客で品質水準に合意すること"}]','"c"','SOAはサービスを組み合わせてシステムを構成する。中文：面向服务架构通过组合业务服务构建系统。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q49','exam-fe','アジャイル開発','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問49・改編】アジャイル開発でイテレーションを行う目的はどれか。','[{"id":"a","text":"短いサイクルで要求との不一致を解消し要求変更に柔軟に対応する"},{"id":"b","text":"タスクの実施状況を常に可視化する"},{"id":"c","text":"ペアプログラミングの役割を固定しない"},{"id":"d","text":"毎日決まった時刻に開発状況を共有する"}]','"a"','短い反復で成果を確認しフィードバックを次の開発に生かす。中文：迭代通过短周期交付和反馈适应需求变化。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q50','exam-fe','マッシュアップ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問50・改編】マッシュアップを利用してWebコンテンツを表示する例はどれか。','[{"id":"a","text":"ブラウザにプラグインを組み込み動画を表示する"},{"id":"b","text":"地図をページ切替なしでスクロールする"},{"id":"c","text":"鉄道経路の検索結果に各社ページへのリンクを表示する"},{"id":"d","text":"店舗案内ページに他サイトの地図検索機能の出力を表示する"}]','"d"','異なるサービスの機能やデータを組み合わせて表示する。中文：将其他服务提供的地图功能组合到店铺页面属于混搭。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q52','exam-fe','ガントチャート','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問52・改編】工程管理や進捗管理に使用するガントチャートの特徴はどれか。','[{"id":"a","text":"各作業の開始時点と終了時点を一目で把握できる"},{"id":"b","text":"各作業の構成要素を示すので管理しやすい"},{"id":"c","text":"各作業の前後関係とクリティカルパスが明確になる"},{"id":"d","text":"各作業の余裕日数が容易に把握できる"}]','"a"','ガントチャートは作業期間を横棒で表し開始・終了や進捗を把握しやすい。中文：甘特图以横条表示各项工作的起止时间和进度。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q53','exam-fe','クリティカルパス','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問53・改編】作業Aの後にB,C,Dに分岐する。BとC→EはG,Hの開始に必要、C→Iもある。G→L、H→K、IはN前に合流、D→F→J→Mは終点へ向かう。日数はA5,B15,C10,D4,E8,F15,G12,H7,I24,J13,K10,L7,M5,N3。クリティカルパスはどれか。','[{"id":"a","text":"A→B→G→L→N"},{"id":"b","text":"A→B→H→K→N"},{"id":"c","text":"A→C→E→G→L→N"},{"id":"d","text":"A→C→I→N"}]','"c"','各経路の日数は順に42、40、45、42日。D経路も42日で、最長は45日。中文：逐条求和，A-C-E-G-L-N共45天，为最长路径。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q55','exam-fe','逓減課金','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問55・改編】使用量に対する累計課金額を表すグラフのうち、逓減課金方式を表すものはどれか。','[{"id":"a","text":"使用量が増えると累計額自体が減少する"},{"id":"b","text":"累計額が一定の割合で増え、途中から増えなくなる"},{"id":"c","text":"累計額は増え続けるが、使用量が増えるにつれ傾きが小さくなる"},{"id":"d","text":"累計額の傾きが使用量とともに大きくなる"}]','"c"','使用量が増えるほど追加分の単価が下がるため、累計額の傾きは小さくなる。中文：递减计费的累计金额继续增长，但单位增量费用逐步降低。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q58','exam-fe','監査ウォークスルー','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問58・改編】システム監査のウォークスルー法として最も適切なものはどれか。','[{"id":"a","text":"監査人が用意したテストデータを対象プログラムで処理する"},{"id":"b","text":"関係者に口頭で問い合わせる"},{"id":"c","text":"関連する資料と文書を入手して点検する"},{"id":"d","text":"データの生成から入力、処理、出力、活用までの過程とコントロールを書面上または実際に追跡する"}]','"d"','処理の流れを実際または文書上で追跡し、組み込まれた統制を確認する。中文：穿行测试沿数据处理流程追踪并检查控制措施。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q59','exam-fe','インシデント管理監査','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問59・改編】インシデント管理の監査で指摘すべき状況はどれか。','[{"id":"a","text":"対応手順を作成し関係者に周知している"},{"id":"b","text":"データベース被害に備え規程に従ってバックアップしている"},{"id":"c","text":"種類、発生箇所、影響度に関係なく連絡・報告ルートが共通である"},{"id":"d","text":"全インシデントの記録と責任者の承認を定めている"}]','"c"','種類や影響度に応じて適切な連絡・報告先にエスカレーションする必要がある。中文：应依事件类型和影响程度设置恰当的报告及升级路径。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q60','exam-fe','可用性の監査','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問60・改編】情報セキュリティ監査で可用性を確認する項目はどれか。','[{"id":"a","text":"外部記憶媒体の無断持出しが禁止されている"},{"id":"b","text":"中断時間を定めたSLAの水準が維持されている"},{"id":"c","text":"データ入力時のエラーチェックが適切に行われている"},{"id":"d","text":"データベースが暗号化されている"}]','"b"','可用性は必要なときに利用可能であること。中断時間はその指標になる。中文：可用性关注需要时服务能否使用，SLA中断时间是相关指标。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q61','exam-fe','IT投資事前評価','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問61・改編】IT投資の事前評価の説明はどれか。','[{"id":"a","text":"計画と実績の差異・原因を分析し投資額の変更要否を判断する"},{"id":"b","text":"事前目標の達成状況を評価し改善策を検討する"},{"id":"c","text":"実現時期とデータ収集方法を計画しその時期に評価する"},{"id":"d","text":"投資目的に基づく効果目標を設定し実施可否判断の情報を提供する"}]','"d"','投資前に目標や期待効果を明確にし、意思決定に必要な情報を用意する。中文：事前评价设定投资目标及预期效果，支持是否实施的决策。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q63','exam-fe','デジタルディバイド','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問63・改編】デジタルディバイドの解消に向けた取組はどれか。','[{"id":"a","text":"IT投資額と効果目標を設定し事前評価する"},{"id":"b","text":"ITを使って家電などを省エネルギー化する"},{"id":"c","text":"情報リテラシの習得機会を増やし情報機器やサービスを利用しやすくする"},{"id":"d","text":"製品の流通情報をICタグで追跡可能にする"}]','"c"','情報通信技術を利用する機会や能力の格差を縮める。中文：通过培训和改善使用环境缩小数字鸿沟。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q65','exam-fe','RFP','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問65・改編】システム調達で、発注元が調達対象や条件を示しベンダに提案書の提出を依頼する段階はどれか。','[{"id":"a","text":"RFI"},{"id":"b","text":"RFP"},{"id":"c","text":"供給者の選定"},{"id":"d","text":"契約の締結"}]','"b"','RFPは提案依頼書。RFIは情報提供依頼。中文：RFP是向供应商提出方案的请求，RFI是信息征询。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q66','exam-fe','垂直統合','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問66・改編】M&Aによる垂直統合の例はどれか。','[{"id":"a","text":"銀行が保険会社を買収する"},{"id":"b","text":"自動車メーカーが別の自動車メーカーを買収する"},{"id":"c","text":"製鉄メーカーが鉄鉱石採掘会社を買収する"},{"id":"d","text":"電機メーカーが不動産会社を買収する"}]','"c"','製鉄と原料採掘は同一サプライチェーンの異なる段階。中文：钢铁厂收购上游矿业公司属于纵向整合。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q67','exam-fe','コストプラス価格','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問67・改編】コストプラス法による価格設定はどれか。','[{"id":"a","text":"価格分析で利益最大とリスク最小を考え段階的に決める"},{"id":"b","text":"値引きを前提に当初からマージンを加える"},{"id":"c","text":"市場で競争可能と推定できる水準で決める"},{"id":"d","text":"製造原価や営業費などの費用総額に希望マージンを加える"}]','"d"','費用を基準に所定の利益を上乗せする。中文：成本加成定价以总成本为基础加上目标利润。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q68','exam-fe','バランススコアカード','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問68・改編】財務、顧客、内部ビジネスプロセス、学習と成長の四つの視点を関連付けて目標と施策を策定する手法はどれか。','[{"id":"a","text":"コアコンピタンス"},{"id":"b","text":"セグメンテーション"},{"id":"c","text":"バランススコアカード"},{"id":"d","text":"プロダクトポートフォリオマネジメント"}]','"c"','バランススコアカードは複数の視点で戦略を具体的な指標と施策に落とし込む。中文：平衡计分卡从财务、客户、内部流程、学习成长四方面落实战略。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q71','exam-fe','アカウントアグリゲーション','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問71・改編】フィンテックのアカウントアグリゲーションの特徴はどれか。','[{"id":"a","text":"複数の金融機関の口座取引情報をまとめて表示する"},{"id":"b","text":"少額に限り送金サービスを提供する"},{"id":"c","text":"電子手形の債権の一部を分割して譲渡する"},{"id":"d","text":"購入者の代金を立替払いして商品を早く届ける"}]','"a"','複数の口座情報をまとめて確認できるサービス。中文：账户聚合将多个金融账户的交易信息集中显示。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q72','exam-fe','エスクロー','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問72・改編】ネットオークションのエスクローサービスの説明はどれか。','[{"id":"a","text":"個人情報保護基準を第三者が監視する"},{"id":"b","text":"メールの送信元とアドレスを認証する"},{"id":"c","text":"クレジットカード情報の暗号化と店の認証を行う"},{"id":"d","text":"決済を仲介し落札者から受けた代金を商品の受渡し完了後に出品者へ送金する"}]','"d"','第三者が代金を預かり、条件成立後に支払うことで取引上のリスクを軽減する。中文：第三方先保管货款，交易条件满足后再转给卖家。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q75','exam-fe','ナッシュ均衡','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問75・改編】A社とB社がそれぞれ戦略1か2を選ぶ。市場シェア(A,B)は(a1,b1)=(40,20)、(a1,b2)=(50,30)、(a2,b1)=(30,10)、(a2,b2)=(25,25)。互いに相手の選択に対し自社のシェアが最大となる組合せはどれか。','[{"id":"a","text":"a1,b1"},{"id":"b","text":"a1,b2"},{"id":"c","text":"a2,b1"},{"id":"d","text":"a2,b2"}]','"b"','Bのどちらの選択でもAはa1が有利。Aのどちらの選択でもBはb2が有利。中文：A的最优策略为a1，B为b2，因此均衡是(a1,b2)。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q76','exam-fe','経済的発注量','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問76・改編】1回当たり発注量Q、発注費用C、1単位当たり年間保管費H、年間需要量Rとする。総費用QH/2＋RC/Qが最小となる発注量を表す式はどれか。','[{"id":"a","text":"√(2RC/H)"},{"id":"b","text":"QH/2＋RC/Q"},{"id":"c","text":"RC/Q"},{"id":"d","text":"QH/2"}]','"a"','経済的発注量は年間保管費と発注費の合計を最小にする√(2RC/H)。中文：经济订货量使年订货费用与保管费用之和最小。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q77','exam-fe','線形計画法','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問77・改編】一次式で表される制約の下で資源を配分し、一次式の効果を最大化する問題を解く手法はどれか。','[{"id":"a","text":"因子分析法"},{"id":"b","text":"回帰分析法"},{"id":"c","text":"実験計画法"},{"id":"d","text":"線形計画法"}]','"d"','目的関数と制約条件が線形の最適化問題を線形計画法で解く。中文：线性规划用于在线性约束下优化线性目标。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q78','exam-fe','キャッシュフロー','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問78・改編】キャッシュフローを改善する行為はどれか。','[{"id":"a","text":"受取手形の期日を長くする"},{"id":"b","text":"売掛金を回収するまでの期間を短くする"},{"id":"c","text":"買掛金を支払うまでの期間を短くする"},{"id":"d","text":"支払手形の期日を短くする"}]','"b"','売掛金を早く回収すると資金が早く流入する。中文：缩短应收账款回收期可加快现金流入。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20211212-q80','exam-fe','請負と派遣','standard','single_choice','【IPA 2021年度 修了認定試験 2021-12-12 問80・改編】請負契約を締結していても労働者派遣とみなされる受託者の行為はどれか。','[{"id":"a","text":"休暇取得の承認を発注者側の指示に従って行う"},{"id":"b","text":"業務遂行の指導や評価を自ら行う"},{"id":"c","text":"勤務規律や職場秩序を保持する"},{"id":"d","text":"発注者の要請を受託者側の責任者が窓口となって受ける"}]','"a"','発注者が労働者の労務管理に指示する実態は請負と派遣の区別で問題になる。中文：即使名为承包，发包方实际指挥劳动管理也可能被认定为派遣。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20211212_FE.pdf','ja','A','explicit','standard','fe_exemption');
